begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temp table lifecycle(id uuid,application_id uuid,preview jsonb,result jsonb);
create temp table preserved as select md5(jsonb_agg(to_jsonb(x) order by x.id)::text) fingerprint,'children' kind from app_private.registration_children x union all select md5(jsonb_agg(to_jsonb(x) order by x.id)::text),'payments' from app_private.payment_requests x union all select md5(jsonb_agg(to_jsonb(x) order by x.id)::text),'registrations' from app_private.registrations x;
select api.portal_registration_begin('duindorp-halloween-2026','parent-size-5@example.invalid','Verkeerde aanmeldroute','0612345678','','','','',repeat('a',64));
insert into lifecycle(id) select id from app_private.portal_registration_intakes where normalized_email='parent-size-5@example.invalid';
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
update lifecycle set preview=api.admin_portal_registration_preview('duindorp-halloween-2026','intake',id);
select is((select preview->'draft'->>'contactName' from lifecycle),'Verkeerde aanmeldroute','an unclaimed intake has an editable authoritative preview without making a portal');
select lives_ok($$select api.admin_portal_registration_apply('duindorp-halloween-2026','intake',id,'edit','{"contactName":"Gecorrigeerde contactnaam"}',preview->>'inputHash','Naam in de losse intake corrigeren','lifecycle-edit-intake-01') from lifecycle$$,'organization edits a pre-OTP intake');
select throws_ok($$select api.admin_portal_registration_apply('duindorp-halloween-2026','intake',id,'withdraw','{}',preview->>'inputHash','Foutieve aanmelding intrekken','lifecycle-old-preview-01') from lifecycle$$,'40001','STALE_VERSION','old preview cannot authorize a changed intake');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
update lifecycle set application_id=(api.portal_registration_claim('duindorp-halloween-2026')->>'id')::uuid;
select ok((select application_id is not null from lifecycle),'same verified parent claims the incomplete application');
select lives_ok($$select api.poortenboek_parent('a0000000-0000-0000-0000-000000000005','duindorp-halloween-2026','list')$$,'parent child books remain available alongside an incomplete house role');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
update lifecycle set preview=api.admin_portal_registration_preview('duindorp-halloween-2026','intake',id);
update lifecycle set result=api.admin_portal_registration_apply('duindorp-halloween-2026','intake',id,'withdraw','{}',preview->>'inputHash','Ouder koos de verkeerde aanmeldroute','lifecycle-withdraw-01');
select is((select result->>'ordinaryRegistrationPreserved' from lifecycle),'true','withdrawal explicitly preserves ordinary participation');
select is((select review_status::text from app_private.portal_applications where id=(select application_id from lifecycle)),'withdrawn','incomplete application is withdrawn without approval or an operational portal');
select is((select api.admin_portal_registration_apply('duindorp-halloween-2026','intake',id,'withdraw','{}',preview->>'inputHash','Ouder koos de verkeerde aanmeldroute','lifecycle-withdraw-01') from lifecycle),(select result from lifecycle),'uncertain retry returns the original receipt');
select is((select count(*) from app_private.portals where application_id=(select application_id from lifecycle)),0::bigint,'lifecycle never needs a fabricated portal');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
select throws_ok($$select api.portal_registration_claim('duindorp-halloween-2026')$$,'23514','PORTAL_REGISTRATION_WITHDRAWN','old OTP claim cannot revive withdrawn participation');
select throws_ok($$select api.portal_application_save('duindorp-halloween-2026','{}',1)$$,'23514','PORTAL_REGISTRATION_WITHDRAWN','a late save cannot revive the application');
select lives_ok($$select api.poortenboek_parent('a0000000-0000-0000-0000-000000000005','duindorp-halloween-2026','list')$$,'same parent keeps safe book selection after withdrawal');
select ok(exists(select 1 from jsonb_array_elements(api.participant_context('duindorp-halloween-2026')->'roles') role where role->>'key'='walker'),'parent environment role survives withdrawal');
select throws_ok($$select api.admin_portal_registration_preview('duindorp-halloween-2026','intake',(select id from lifecycle))$$,'42501','NOT_AUTHORIZED','ordinary parent cannot inspect private organization lifecycle data');
select lives_ok($$select api.portal_registration_restart('duindorp-halloween-2026')$$,'verified parent can deliberately restart their unused application');
select is((select review_status::text from app_private.portal_applications where id=(select application_id from lifecycle)),'draft','deliberate restart uses the existing application identity');
select is((select md5(jsonb_agg(to_jsonb(x) order by x.id)::text) from app_private.registration_children x),(select fingerprint from preserved where kind='children'),'all registration-child rows and statuses preserved');
select is((select md5(jsonb_agg(to_jsonb(x) order by x.id)::text) from app_private.payment_requests x),(select fingerprint from preserved where kind='payments'),'all payment rows and history preserved');
select is((select md5(jsonb_agg(to_jsonb(x) order by x.id)::text) from app_private.registrations x),(select fingerprint from preserved where kind='registrations'),'all ordinary registration fields preserved');
select ok(not has_function_privilege('anon','api.admin_portal_registration_apply(text,text,uuid,text,jsonb,text,text,text)','execute'),'no anonymous lifecycle mutation');
select * from finish();
rollback;
